import {chromium} from 'playwright';import {mkdir,writeFile} from 'node:fs/promises';import assert from 'node:assert/strict';import {HRA_ORGAN_TARGETS} from '../../src/simulator/data/hraOrgans.ts';
const out=process.env.ORBIT_FOCUS_OUT||'/tmp/orbit-reference-focus';await mkdir(out,{recursive:true});const b=await chromium.launch({args:['--use-angle=swiftshader','--enable-unsafe-swiftshader']});const p=await b.newPage({viewport:{width:393,height:800},isMobile:true,hasTouch:true});await p.route(/https:\/\/(?:[^/]+\.)?(?:googlesyndication\.com|doubleclick\.net|googleadservices\.com)\//,r=>r.abort());
const targets=HRA_ORGAN_TARGETS.filter(t=>!t.matchAll&&(t.modelKeys.includes('blood_vasculature')||t.organKey==='knee')),report={checks:[],errors:[]};p.on('pageerror',e=>report.errors.push(e.message));let current;
async function ready(){await p.getByTestId('anatomy-renderer').locator('canvas').waitFor();await p.waitForFunction(()=>!/LOADING (BODYPARTS3D|Z-ANATOMY|HRA)/.test(document.querySelector('[data-testid="anatomy-renderer"]').textContent),null,{timeout:180000});await p.waitForTimeout(650);}
async function selectedPixels(){return p.getByTestId('anatomy-renderer').locator('canvas').evaluate(c=>new Promise(resolve=>requestAnimationFrame(()=>{const gl=c.getContext('webgl2')||c.getContext('webgl'),w=gl.drawingBufferWidth,h=gl.drawingBufferHeight,a=new Uint8Array(w*h*4);gl.readPixels(0,0,w,h,gl.RGBA,gl.UNSIGNED_BYTE,a);let count=0;for(let i=0;i<a.length;i+=4)if(a[i]>150&&a[i+1]>90&&a[i+2]>a[i]*1.05)count++;resolve({count,w,h});})));}
try{for(const t of targets){const first=HRA_ORGAN_TARGETS.find(x=>x.organKey===t.organKey&&x.matchAll)||t;if(current!==first.id){await p.goto('http://127.0.0.1:4180/simulator?mode=anatomy&organ='+t.organKey+'&isolate='+first.id+'&nativeTheme=dark');await ready();const d=p.getByTestId('organ-detail-drawer');if(await d.isVisible())await d.getByRole('button',{name:'Close',exact:true}).click();current=first.id;}
 await p.getByTitle(t.label,{exact:true}).click();await p.getByTestId('anatomy-renderer').locator('canvas').scrollIntoViewIfNeeded();await ready();let frame;for(let i=0;i<20;i++){frame=await selectedPixels();if(frame.count>0)break;await p.waitForTimeout(250);}await p.screenshot({path:out+'/'+t.id+'.png'});report.checks.push({id:t.id,...frame});console.log(t.id,frame.count);if(process.env.ORBIT_FOCUS_EXPECT_FIXED==='1'&&['hra_coronary_arteries','hra_knee_menisci','hra_knee_cartilage'].includes(t.id))assert(frame.count>100,t.id+' selected structures are not readable');}
 assert.equal(report.checks.length,14);assert.deepEqual(report.errors,[]);report.status='PASSED';}
catch(e){report.status='FAILED';report.failure=e.stack;throw e;}finally{await writeFile(out+'/results.json',JSON.stringify(report,null,2));await b.close();}
